int iwgif_read_and_process_image(struct iwgifrcontext *rctx) {
    // Read image header
    uint8_t image_header[6];
    if (fread(image_header, 1, sizeof(image_header), rctx->fp) != sizeof(image_header)) {
        return 0;
    }

    // Extract image dimensions and interlacing
    rctx->image_left = (image_header[0] << 8) | image_header[1];
    rctx->image_top = (image_header[2] << 8) | image_header[3];
    rctx->image_width = (image_header[4] << 8) | image_header[5];

    rctx->interlaced = (image_header[0] >> 7) & 0x01;

    // Check for local color table
    uint8_t packed_fields = image_header[0];
    if (packed_fields & 0x80) {
        uint8_t color_table_size = 1 << ((packed_fields & 0x07) + 1);
        if (rctx->image_palette == NULL) {
            rctx->image_palette = (gif_color_t *)malloc(color_table_size * sizeof(gif_color_t));
            if (rctx->image_palette == NULL) {
                return 0;
            }
        }
        if (fread(rctx->image_palette, sizeof(gif_color_t), color_table_size, rctx->fp) != color_table_size) {
            return 0;
        }

        // Handle transparency
        if (rctx->transparent_index != -1) {
            rctx->image_palette[rctx->transparent_index].red = 0;
            rctx->image_palette[rctx->transparent_index].green = 0;
            rctx->image_palette[rctx->transparent_index].blue = 0;
            rctx->image_palette[rctx->transparent_index].alpha = 0;
        }
    }

    // Read LZW code size
    uint8_t lzw_code_size;
    if (fread(&lzw_code_size, 1, sizeof(lzw_code_size), rctx->fp) != sizeof(lzw_code_size)) {
        return 0;
    }

    if (lzw_code_size < 1 || lzw_code_size > 8) {
        return 0;
    }

    rctx->lzw_code_size = lzw_code_size;

    // Initialize screen context
    rctx->current_line = 0;
    rctx->line_index = 0;

    // Read and process subblocks of pixel data
    while (!feof(rctx->fp)) {
        uint8_t subblock_size;
        if (fread(&subblock_size, 1, sizeof(subblock_size), rctx->fp) != sizeof(subblock_size)) {
            return 0;
        }

        if (subblock_size == 0) {
            break;
        }

        uint8_t subblock_data[256];
        if (fread(subblock_data, 1, subblock_size, rctx->fp) != subblock_size) {
            return 0;
        }

        if (!lzw_decode_subblock(rctx, subblock_data, subblock_size)) {
            return 0;
        }
    }

    return 1;
}

int iwgif_read_image(struct iwgifrcontext *rctx) {
    if (!rctx) {
        return 0;
    }

    // Read image header
    unsigned char image_header[6];
    if (fread(image_header, 1, sizeof(image_header), rctx->file) != sizeof(image_header)) {
        return 0;
    }

    // Extract dimensions and interlacing
    rctx->image.left = (image_header[0] << 8) | image_header[1];
    rctx->image.top = (image_header[2] << 8) | image_header[3];
    rctx->image.width = (image_header[4] << 8) | image_header[5];

    // Check for local color table
    unsigned char flags = image_header[6];
    if (flags & 0x80) {
        if (!iwgif_init_color_table(rctx, flags & 0x07)) {
            return 0;
        }
    }

    // Handle transparency
    rctx->transparent_index = -1;
    if (flags & 0x01) {
        rctx->transparent_index = rctx->color_table[flags & 0x07].palette[rctx->transparent_index];
    }

    // Read LZW code size
    int lzw_code_size = fgetc(rctx->file);
    if (lzw_code_size < 1 || lzw_code_size > 12) {
        return 0;
    }

    // Initialize screen context
    if (!iwgif_init_screen(rctx)) {
        return 0;
    }

    // Read pixel data in subblocks
    int bytes_read;
    do {
        int subblock_size = fgetc(rctx->file);
        if (subblock_size == 0) {
            break;
        }

        if (!iwgif_read_lzw_block(rctx, lzw_code_size, subblock_size)) {
            return 0;
        }
    } while (!feof(rctx->file));

    return 1;
}

int iwgif_read_and_process_image(struct iwgifrcontext *rctx) {
    if (!rctx) {
        return 0;
    }

    // Read image header
    unsigned char image_header[6];
    if (fread(image_header, sizeof(unsigned char), 6, rctx->file) != 6) {
        return 0;
    }

    rctx->width = (image_header[1] << 8) | image_header[0];
    rctx->height = (image_header[3] << 8) | image_header[2];
    rctx->interlaced = (image_header[4] & 0x40) ? 1 : 0;

    // Check for local color table
    int has_local_color_table = (image_header[4] & 0x80) ? 1 : 0;
    if (has_local_color_table) {
        int color_table_size = 2 << ((image_header[4] & 0x07) + 1);
        if (rctx->color_table) {
            free(rctx->color_table);
        }
        rctx->color_table = malloc(color_table_size * sizeof(struct gif_color));
        if (!rctx->color_table) {
            return 0;
        }

        for (int i = 0; i < color_table_size; i++) {
            unsigned char red, green, blue;
            if (fread(&red, sizeof(unsigned char), 1, rctx->file) != 1 ||
                fread(&green, sizeof(unsigned char), 1, rctx->file) != 1 ||
                fread(&blue, sizeof(unsigned char), 1, rctx->file) != 1) {
                return 0;
            }

            rctx->color_table[i].red = red;
            rctx->color_table[i].green = green;
            rctx->color_table[i].blue = blue;
        }

        rctx->color_table_size = color_table_size;
    }

    rctx->transparent_index = -1;
    if (rctx->color_table && (image_header[4] & 0x01)) {
        if (fread(&rctx->transparent_index, sizeof(int), 1, rctx->file) != 1) {
            return 0;
        }
        if (rctx->transparent_index >= 0 && rctx->transparent_index < rctx->color_table_size) {
            rctx->color_table[rctx->transparent_index].alpha = 0;
        }
    }

    // Read LZW minimum code size
    unsigned char lzw_code_size;
    if (fread(&lzw_code_size, sizeof(unsigned char), 1, rctx->file) != 1) {
        return 0;
    }

    if (lzw_code_size < 1 || lzw_code_size > 8) {
        return 0;
    }

    // Initialize screen context
    rctx->image_data = (unsigned char *)malloc(rctx->width * rctx->height);
    if (!rctx->image_data) {
        return 0;
    }

    int byte_count;
    unsigned char subblock_size;
    do {
        if (fread(&subblock_size, sizeof(unsigned char), 1, rctx->file) != 1) {
            return 0;
        }

        byte_count = subblock_size;
        if (byte_count > 0) {
            if (rctx->lzw_decoder(rctx->file, rctx->image_data, &byte_count, lzw_code_size) < 0) {
                return 0;
            }
        }
    } while (subblock_size != 0);

    if (byte_count < (rctx->width * rctx->height)) {
        return 0;
    }

    return 1;
}

int iwgif_read_image(struct iwgifrcontext *rctx) {
    uint8_t image_header[6];
    uint8_t flags;

    // Read image header
    if (fread(image_header, sizeof(uint8_t), 6, rctx->file) != 6)
        return 0;

    // Extract dimensions and interlacing info
    rctx->image.left = (image_header[1] << 8) | image_header[0];
    rctx->image.top = (image_header[3] << 8) | image_header[2];
    rctx->image.width = (image_header[3] << 8) | image_header[2];
    rctx->image.height = (image_header[5] << 8) | image_header[4];
    flags = image_header[5];

    rctx->image.interlaced = (flags >> 6) & 1;
    rctx->image.local_color_table = (flags >> 7) & 1;

    // Initialize local color table if present
    if (rctx->image.local_color_table) {
        int color_table_size = 1 << ((flags & 0x07) + 1);
        rctx->color_table = malloc(color_table_size * 3);
        if (!rctx->color_table)
            return 0;

        if (fread(rctx->color_table, 1, color_table_size * 3, rctx->file) != color_table_size * 3) {
            free(rctx->color_table);
            return 0;
        }

        rctx->color_table_size = color_table_size;
        // Handle transparency if present
        if (rctx->image.transparency_index != 0xFF) {
            for (int i = 0; i < color_table_size; i++) {
                rctx->color_table[i * 3 + 3] = (i == rctx->image.transparency_index) ? 0x00 : 0xFF;
            }
        }
    }

    // Read LZW code size
    if (fread(&rctx->lzw_code_size, sizeof(uint8_t), 1, rctx->file) != 1)
        return 0;

    if (rctx->lzw_code_size < 2 || rctx->lzw_code_size > 8)
        return 0;

    // Initialize screen context and LZW decoding
    if (!iwgif_init_screen(rctx))
        return 0;

    // Read pixel data subblocks
    while (1) {
        uint8_t subblock_size;
        if (fread(&subblock_size, sizeof(uint8_t), 1, rctx->file) != 1)
            return 0;

        if (subblock_size == 0)
            break;

        uint8_t *subblock = malloc(subblock_size);
        if (!subblock)
            return 0;

        if (fread(subblock, 1, subblock_size, rctx->file) != subblock_size) {
            free(subblock);
            return 0;
        }

        if (!iwgif_decode_subblock(rctx, subblock, subblock_size)) {
            free(subblock);
            return 0;
        }

        free(subblock);
    }

    return 1;
}

